### [P2] (1/3) Add a shared display transform for standalone combining marks

The new preview and multi-code-point description paths both format raw mapped/code-point strings. Add one display-only helper that prefixes a dotted circle only when every code point is a combining mark, then use it at both call sites. Keep the mapped and copied values unchanged.

```suggestion
    /// <summary>
    /// Returns display text for a character, prefixing a dotted circle when it contains
    /// only combining marks.
    /// </summary>
    public static string GetDisplayText(string character)
    {
        if (string.IsNullOrEmpty(character))
        {
            return character;
        }

        for (var index = 0; index < character.Length;)
        {
            var category = System.Globalization.CharUnicodeInfo.GetUnicodeCategory(character, index);
            if (category is not System.Globalization.UnicodeCategory.NonSpacingMark
                and not System.Globalization.UnicodeCategory.SpacingCombiningMark
                and not System.Globalization.UnicodeCategory.EnclosingMark)
            {
                return character;
            }

            index += char.IsHighSurrogate(character[index]) ? 2 : 1;
        }

        return "◌" + character;
    }

